package com.etashe.tunnelvpn.core

import org.json.JSONObject
import java.net.URI
import java.net.URLDecoder

class LinkParseException(message: String) : Exception(message)

/**
 * Parses share links (vless://, vmess://, trojan://, ss://) into a [ConfigProfile].
 * Mirrors the de-facto community formats used by Xray/V2Ray clients (v2rayN / v2rayNG / NetMod style),
 * so links generated by any standard panel or by our own backend import correctly.
 */
object LinkParser {

    fun parse(rawLink: String): ConfigProfile {
        val link = rawLink.trim()
        return when {
            link.startsWith("vless://", ignoreCase = true) -> parseVless(link)
            link.startsWith("vmess://", ignoreCase = true) -> parseVmess(link)
            link.startsWith("trojan://", ignoreCase = true) -> parseTrojan(link)
            link.startsWith("ss://", ignoreCase = true) -> parseShadowsocks(link)
            else -> throw LinkParseException("رابط غير مدعوم. يجب أن يبدأ بـ vless:// أو vmess:// أو trojan:// أو ss://")
        }
    }

    fun isSupportedLink(text: String): Boolean {
        val t = text.trim()
        return t.startsWith("vless://", true) || t.startsWith("vmess://", true) ||
            t.startsWith("trojan://", true) || t.startsWith("ss://", true)
    }

    // ---------------------------------------------------------------- VLESS
    // vless://uuid@host:port?encryption=none&security=tls&sni=...&type=ws&path=...&host=...#remark
    private fun parseVless(link: String): ConfigProfile {
        val uri = safeUri(link)
        val uuid = uri.userInfo ?: throw LinkParseException("رابط VLESS غير صالح: لا يوجد UUID")
        val params = queryParams(uri)
        val profile = ConfigProfile(
            engine = EngineType.XRAY,
            protocol = XrayProtocol.VLESS,
            address = uri.host ?: "",
            port = resolvePort(uri.port, params["security"]),
            uuid = uuid,
            flow = params["flow"] ?: "",
            network = XrayNetwork.fromWire(params["type"]),
            path = decode(params["path"]) ?: "/",
            host = params["host"] ?: "",
            serviceName = params["serviceName"] ?: "",
            tlsEnabled = params["security"].equals("tls", true) || params["security"].equals("reality", true),
            sni = params["sni"] ?: "",
            alpn = params["alpn"] ?: "",
            allowInsecure = params["allowInsecure"] == "1" || params["allowInsecure"].equals("true", true),
            remark = fragment(uri) ?: "VLESS Server"
        )
        requireAddress(profile)
        return profile
    }

    // --------------------------------------------------------------- VMESS
    // vmess://base64(json)  where json = {v,ps,add,port,id,aid,net,type,host,path,tls,sni,scy}
    private fun parseVmess(link: String): ConfigProfile {
        val b64 = link.removePrefix("vmess://").removePrefix("VMESS://").trim()
        val jsonStr = decodeB64Flexible(b64)
            ?: throw LinkParseException("تعذر فك تشفير رابط VMess: البيانات ليست Base64 صالح")
        val json = try {
            JSONObject(jsonStr)
        } catch (e: Exception) {
            throw LinkParseException("تعذر قراءة بيانات VMess: الصيغة غير صحيحة")
        }

        val profile = ConfigProfile(
            engine = EngineType.XRAY,
            protocol = XrayProtocol.VMESS,
            address = json.optString("add"),
            port = json.optString("port", "443").toIntOrNull() ?: 443,
            uuid = json.optString("id"),
            alterId = json.optString("aid", "0").toIntOrNull() ?: 0,
            vmessSecurity = json.optString("scy", "auto").ifBlank { "auto" },
            network = XrayNetwork.fromWire(json.optString("net", "tcp")),
            path = json.optString("path", "/").ifBlank { "/" },
            host = json.optString("host"),
            serviceName = json.optString("path"),
            tlsEnabled = json.optString("tls").equals("tls", true),
            sni = json.optString("sni"),
            alpn = json.optString("alpn"),
            allowInsecure = false,
            remark = json.optString("ps").ifBlank { "VMess Server" }
        )
        requireAddress(profile)
        return profile
    }

    // -------------------------------------------------------------- TROJAN
    // trojan://password@host:port?security=tls&sni=...&type=ws&path=...&host=...#remark
    private fun parseTrojan(link: String): ConfigProfile {
        val uri = safeUri(link)
        val password = uri.userInfo ?: throw LinkParseException("رابط Trojan غير صالح: لا توجد كلمة مرور")
        val params = queryParams(uri)
        val profile = ConfigProfile(
            engine = EngineType.XRAY,
            protocol = XrayProtocol.TROJAN,
            address = uri.host ?: "",
            port = resolvePort(uri.port, params["security"] ?: "tls"),
            password = password,
            network = XrayNetwork.fromWire(params["type"]),
            path = decode(params["path"]) ?: "/",
            host = params["host"] ?: "",
            serviceName = params["serviceName"] ?: "",
            tlsEnabled = params["security"]?.equals("none", true) != true,
            sni = params["sni"] ?: "",
            alpn = params["alpn"] ?: "",
            allowInsecure = params["allowInsecure"] == "1" || params["allowInsecure"].equals("true", true),
            remark = fragment(uri) ?: "Trojan Server"
        )
        requireAddress(profile)
        return profile
    }

    // --------------------------------------------------------- SHADOWSOCKS
    // ss://base64(method:password)@host:port#remark   OR   ss://base64(method:password@host:port)#remark
    private fun parseShadowsocks(link: String): ConfigProfile {
        val withoutScheme = link.removePrefix("ss://").removePrefix("SS://")
        val hashIdx = withoutScheme.indexOf('#')
        val remark = if (hashIdx >= 0) decode(withoutScheme.substring(hashIdx + 1)) else null
        val body = if (hashIdx >= 0) withoutScheme.substring(0, hashIdx) else withoutScheme

        val atIdx = body.lastIndexOf('@')
        val (method, password, host, port) = if (atIdx >= 0) {
            // method:password is base64, host:port is plain
            val userInfoRaw = body.substring(0, atIdx)
            val hostPort = body.substring(atIdx + 1)
            val decodedUserInfo = decodeB64Flexible(userInfoRaw)
                ?: userInfoRaw // some generators leave it plain
            val methodPass = decodedUserInfo.split(":", limit = 2)
            val hp = hostPort.split(":", limit = 2)
            Quad(
                methodPass.getOrElse(0) { "" },
                methodPass.getOrElse(1) { "" },
                hp.getOrElse(0) { "" },
                hp.getOrElse(1) { "443" }.toIntOrNull() ?: 443
            )
        } else {
            // whole thing is base64: method:password@host:port
            val decoded = decodeB64Flexible(body)
                ?: throw LinkParseException("تعذر فك تشفير رابط Shadowsocks")
            val atIdx2 = decoded.lastIndexOf('@')
            if (atIdx2 < 0) throw LinkParseException("صيغة رابط Shadowsocks غير معروفة")
            val methodPass = decoded.substring(0, atIdx2).split(":", limit = 2)
            val hp = decoded.substring(atIdx2 + 1).split(":", limit = 2)
            Quad(
                methodPass.getOrElse(0) { "" },
                methodPass.getOrElse(1) { "" },
                hp.getOrElse(0) { "" },
                hp.getOrElse(1) { "443" }.toIntOrNull() ?: 443
            )
        }

        val profile = ConfigProfile(
            engine = EngineType.XRAY,
            protocol = XrayProtocol.SHADOWSOCKS,
            address = host,
            port = port,
            ssMethod = method,
            password = password,
            remark = remark?.takeIf { it.isNotBlank() } ?: "Shadowsocks Server"
        )
        requireAddress(profile)
        return profile
    }

    // --------------------------------------------------------------- utils

    private data class Quad(val a: String, val b: String, val c: String, val d: Int)

    private fun safeUri(link: String): URI = try {
        URI(link)
    } catch (e: Exception) {
        throw LinkParseException("رابط غير صالح")
    }

    private fun requireAddress(profile: ConfigProfile) {
        if (profile.address.isBlank()) throw LinkParseException("الرابط لا يحتوي على عنوان سيرفر صالح")
    }

    private fun resolvePort(port: Int, security: String?): Int =
        if (port > 0) port else if (security.equals("tls", true)) 443 else 80

    private fun queryParams(uri: URI): Map<String, String> {
        val query = uri.rawQuery ?: return emptyMap()
        return query.split("&").mapNotNull {
            val idx = it.indexOf('=')
            if (idx < 0) null else {
                val k = it.substring(0, idx)
                val v = decode(it.substring(idx + 1)) ?: ""
                k to v
            }
        }.toMap()
    }

    private fun fragment(uri: URI): String? = uri.rawFragment?.let { decode(it) }

    private fun decode(s: String?): String? = s?.let {
        try {
            URLDecoder.decode(it, "UTF-8")
        } catch (e: Exception) {
            it
        }
    }

    /**
     * Minimal, dependency-free Base64 decoder (standard + URL-safe alphabets,
     * tolerant of missing padding). Deliberately avoids android.util.Base64
     * (not available in plain JVM unit tests) and java.util.Base64
     * (requires API 26+, while this app targets minSdk 21).
     */
    private fun decodeB64Flexible(input: String): String? {
        val cleaned = input.trim().replace("\n", "").replace("\r", "").replace(" ", "+")
        return decodeB64(cleaned, urlSafe = false) ?: decodeB64(cleaned, urlSafe = true)
    }

    private fun decodeB64(input: String, urlSafe: Boolean): String? {
        val alphabet = if (urlSafe)
            "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"
        else
            "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

        val clean = input.trimEnd('=')
        if (clean.isEmpty()) return null

        val out = java.io.ByteArrayOutputStream()
        var buffer = 0
        var bitsCollected = 0
        try {
            for (c in clean) {
                val value = alphabet.indexOf(c)
                if (value < 0) return null
                buffer = (buffer shl 6) or value
                bitsCollected += 6
                if (bitsCollected >= 8) {
                    bitsCollected -= 8
                    out.write((buffer shr bitsCollected) and 0xFF)
                }
            }
        } catch (e: Exception) {
            return null
        }
        return try {
            String(out.toByteArray(), Charsets.UTF_8)
        } catch (e: Exception) {
            null
        }
    }
}
